\documentclass{article}
\usepackage[paperwidth=841mm,paperheight=1189mm,margin=0mm]{geometry}
\usepackage{tcolorbox}
\tcbuselibrary{poster,skins,fitting}
\usepackage{graphicx}
\usepackage{amsmath,amssymb}
\usepackage{enumitem}
\usepackage[table]{xcolor}
\usepackage{lmodern}
\usepackage[T1]{fontenc}
\pagestyle{empty}

% ── Dark data-dashboard theme ──
\definecolor{primary}{HTML}{0B1120}      % deep navy
\definecolor{secondary}{HTML}{1E3A5F}     % midnight blue
\definecolor{accent}{HTML}{00D4FF}        % electric cyan
\definecolor{growth}{HTML}{00E676}       % bright green for positive deltas
\definecolor{bgposter}{HTML}{0B1120}       % dark navy background
\definecolor{carddark}{HTML}{111827}      % card bg
\definecolor{cardborder}{HTML}{1E3A5F}    % card border
\definecolor{textlight}{HTML}{F9FAFB}     % light text
\definecolor{textmuted}{HTML}{9CA3AF}     % muted text
\definecolor{statbg}{HTML}{0F2744}        % stat callout bg
\definecolor{greenbg}{HTML}{003D2E}       % growth indicator bg

\pagecolor{bgposter}
\color{textlight}

% ── List styling ──
\setlist[itemize]{leftmargin=24pt, itemsep=8pt, parsep=2pt, topsep=2pt,
  label={\color{accent}$\blacktriangleright$}}

% ── Card styles ──
\tcbset{
  darkcard/.style={
    enhanced, arc=0pt, boxrule=2pt, colback=carddark,
    borderline west={6pt}{0pt}{accent},
    frame style={color=cardborder, line width=1pt},
    left=18pt, right=16pt, top=6pt, bottom=6pt,
    fonttitle=\fontsize{38}{46}\selectfont\bfseries\color{accent},
    coltitle=accent, colbacktitle=carddark,
    toptitle=6pt, bottomtitle=4pt,
    titlerule=0pt,
    valign=top,
    drop shadow={opacity=0.35, color=black},
  },
  tablecard/.style={
    enhanced, arc=0pt, boxrule=1pt, colback=carddark,
    frame style={color=secondary, line width=1pt},
    left=14pt, right=14pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{38}{46}\selectfont\bfseries\color{accent},
    coltitle=accent, colbacktitle=carddark,
    toptitle=6pt, bottomtitle=4pt,
    titlerule=2pt, titlerule style={color=accent!60},
    valign=top,
  },
  highlightcard/.style={
    enhanced, arc=0pt, boxrule=2pt, colback=statbg,
    borderline west={6pt}{0pt}{growth},
    frame style={color=accent!40, line width=1pt},
    left=16pt, right=14pt, top=6pt, bottom=6pt,
    fonttitle=\fontsize{36}{44}\selectfont\bfseries\color{growth},
    coltitle=growth, colbacktitle=statbg,
    toptitle=5pt, bottomtitle=4pt,
    titlerule=0pt,
    valign=top,
    drop shadow={opacity=0.3},
  },
}

% ── Table styling ──
\rowcolors{1}{carddark}{secondary!30}
\setkeys{Gin}{width=0.98\linewidth}

% ── Bullet macro ──
\newcommand{\pbullet}[1]{\item \fontsize{30}{40}\selectfont #1}

\begin{document}
\begin{tcbposter}[
  coverage={spread},
  poster={columns=3, rows=20, spacing=0mm},
]

% ══ TITLE BAR ═══════════════════════════════════════════════════════
\posterbox[
  enhanced, colback=primary, colframe=primary, colupper=white,
  arc=0pt, boxrule=0pt,
  left=30pt, right=30pt, top=10pt, bottom=8pt,
  halign=center, valign=center,
  drop shadow={opacity=0.5}
]{name=title, column=1, span=3, between=top and row4}{
  {\fontsize{72}{88}\selectfont\bfseries\color{textlight} Open Source Contributor Index}\\[10pt]
  {\fontsize{38}{48}\selectfont\color{accent} March 2026 Rankings}\\[6pt]
  {\fontsize{28}{36}\selectfont\color{textmuted} OSCI — Tracking 239 Organizations Worldwide}
}

% ══ STAT BANNER ══════════════════════════════════════════════════════
\posterbox[
  enhanced, colback=primary!5!carddark, boxrule=0pt, arc=0pt,
  left=10pt, right=10pt, top=4pt, bottom=4pt,
  valign=center,
  borderline top={3pt}{0pt}{accent!50},
  borderline bottom={2pt}{0pt}{secondary!50},
]{name=stats, column=1, span=3, between=row4 and row6}{
  \centering
  \begin{minipage}[c]{0.31\linewidth}\centering
    \fcolorbox{accent!40}{statbg}{\parbox{0.9\linewidth}{%
      \centering\vspace{8pt}%
      {\fontsize{64}{76}\selectfont\bfseries\color{accent} 548}%
      {\fontsize{32}{40}\selectfont\color{growth} \ $\uparrow$128}\\[4pt]
      {\fontsize{26}{34}\selectfont\color{textlight} Google — Active Contributors}\\[2pt]
      {\fontsize{22}{28}\selectfont\color{textmuted} \#1 Ranked}\vspace{8pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.31\linewidth}\centering
    \fcolorbox{accent!40}{statbg}{\parbox{0.9\linewidth}{%
      \centering\vspace{8pt}%
      {\fontsize{64}{76}\selectfont\bfseries\color{accent} 2,721}%
      {\fontsize{32}{40}\selectfont\color{growth} \ $\uparrow$595}\\[4pt]
      {\fontsize{26}{34}\selectfont\color{textlight} Top 10 — Combined}\\[2pt]
      {\fontsize{22}{28}\selectfont\color{textmuted} Active Contributors}\vspace{8pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.31\linewidth}\centering
    \fcolorbox{accent!40}{statbg}{\parbox{0.9\linewidth}{%
      \centering\vspace{8pt}%
      {\fontsize{64}{76}\selectfont\bfseries\color{accent} 239}%
      {\fontsize{32}{40}\selectfont\color{growth}}\ \[4pt]
      {\fontsize{26}{34}\selectfont\color{textlight} Organizations Tracked}\\[2pt]
      {\fontsize{22}{28}\selectfont\color{textmuted} Global OSCI Index}\vspace{8pt}%
    }}
  \end{minipage}
}

% ══ TOP 10 TABLE ════════════════════════════════════════════════════
\posterbox[
  tablecard, title={Top 10 Contributing Organizations}
]{name=toptable, column=1, span=3, between=row6 and row13}{
  \fontsize{28}{36}\selectfont
  \rowcolors{1}{carddark}{secondary!20}
  \setlength{\arrayrulewidth}{1pt}
  \arrayrulecolor{secondary}
  \begin{tabular}{|>{\centering\fontsize{26}{34}\selectfont\color{textlight}\bfseries}r|
                  >{\fontsize{28}{36}\selectfont\color{textlight}}l|
                  >{\centering\fontsize{26}{34}\selectfont\color{growth}}r|
                  >{\centering\fontsize{24}{32}\selectfont\color{growth}}r|
                  >{\centering\fontsize{26}{34}\selectfont\color{textlight}}r|
                  >{\centering\fontsize{24}{32}\selectfont\color{growth}}r|}
    \hline
    \rowcolor{secondary}\multicolumn{1}{|c|}{\fontsize{24}{30}\selectfont\color{textlight}\bfseries Rank} &
    \multicolumn{1}{c|}{\fontsize{24}{30}\selectfont\color{textlight}\bfseries Organization} &
    \multicolumn{1}{c|}{\fontsize{24}{30}\selectfont\color{accent}\bfseries Active} &
    \multicolumn{1}{c|}{\fontsize{24}{30}\selectfont\color{growth}\bfseries MoM} &
    \multicolumn{1}{c|}{\fontsize{24}{30}\selectfont\color{accent}\bfseries Community} &
    \multicolumn{1}{c|}{\fontsize{24}{30}\selectfont\color{growth}\bfseries MoM} \\
    \hline
    \rowcolor{carddark}
    \rowfont{\fontsize{28}{36}\selectfont\color{accent}\bfseries}{1} & \rowfont{\fontsize{28}{36}\selectfont\color{textlight}}{Google} & \rowfont{\fontsize{28}{36}\selectfont\color{growth}\bfseries}{548} & \rowfont{\fontsize{26}{32}\selectfont\color{growth}}{+128} & \rowfont{\fontsize{28}{36}\selectfont\color{textlight}}{1,986} & \rowfont{\fontsize{26}{32}\selectfont\color{growth}}{+267} \\[4pt]
    \rowcolor{secondary!15}
    2 & Microsoft & 438 & +74 & 1,189 & +174 \\[4pt]
    \rowcolor{carddark}
    3 & Red Hat & 432 & +94 & 1,378 & +193 \\[4pt]
    \rowcolor{secondary!15}
    4 & AMD & 233 & +66 & 627 & +109 \\[4pt]
    \rowcolor{carddark}
    5 & Datadog & 221 & +34 & 411 & +58 \\[4pt]
    \rowcolor{secondary!15}
    6 & Intel & 217 & +48 & 707 & +82 \\[4pt]
    \rowcolor{carddark}
    7 & NVIDIA & 194 & +41 & 650 & +106 \\[4pt]
    \rowcolor{secondary!15}
    8 & SUSE & 158 & +32 & 353 & +51 \\[4pt]
    \rowcolor{carddark}
    9 & IBM & 140 & +44 & 616 & +133 \\[4pt]
    \rowcolor{secondary!15}
    10 & SAP & 140 & +34 & 378 & +54 \\[4pt]
    \hline
  \end{tabular}\\[6pt]
  {\fontsize{24}{30}\selectfont\color{textmuted} Source: OSCI (Open Source Contributor Index), March 2026}
}

% ══ LANGUAGE SECTION ════════════════════════════════════════════════
\posterbox[
  darkcard, title={Top Programming Languages}
]{name=languages, column=1, span=1, between=row13 and row17}{
  \fontsize{30}{40}\selectfont\color{textlight}
  \begin{itemize}
    \pbullet{{\fontsize{36}{44}\selectfont\bfseries\color{accent} Python} \ — 20.3\%}
    \pbullet{{\fontsize{36}{44}\selectfont\bfseries\color{accent} C++} \ — 14.3\%}
    \pbullet{{\fontsize{36}{44}\selectfont\bfseries\color{accent} Go} \ — 11.6\%}
    \pbullet{{\fontsize{36}{44}\selectfont\bfseries\color{accent} C} \ — 10.9\%}
    \pbullet{{\fontsize{36}{44}\selectfont\bfseries\color{accent} TypeScript} \ — 10.5\%}
    \pbullet{{\fontsize{36}{44}\selectfont\bfseries\color{accent} Java} \ — 4.4\%}
  \end{itemize}
}

% ══ LICENSE SECTION ════════════════════════════════════════════════
\posterbox[
  darkcard, title={Dominant Licenses}
]{name=licenses, column=2, span=1, between=row13 and row17}{
  \fontsize{30}{40}\selectfont\color{textlight}
  \begin{enumerate}
    \item {\fontsize{36}{44}\selectfont\bfseries\color{accent} Apache-2.0} \ Most prevalent
    \item {\fontsize{36}{44}\selectfont\bfseries\color{accent} MIT} \ Permissive
    \item {\fontsize{36}{44}\selectfont\bfseries\color{accent} GPL-2.0} \ Copyleft
  \end{itemize}
  \vspace{8pt}
  \colorbox{statbg}{\parbox{0.9\linewidth}{%
    {\fontsize{26}{34}\selectfont\color{textmuted} Apache-2.0 \& MIT dominate, reflecting enterprise-friendly permissive licensing.}}
}

% ══ GROWTH SECTION ═════════════════════════════════════════════════
\posterbox[
  highlightcard, title={Growth Momentum}
]{name=growth, column=3, span=1, between=row13 and row17}{
  \fontsize{28}{38}\selectfont\color{textlight}
  \begin{itemize}
    \pbullet{Top 10 added \colorbox{growth!25}{\parbox{0.8\linewidth}{{\fontsize{32}{40}\selectfont\bfseries\color{growth} +595} active contributors}}}
    \pbullet{All 10 orgs \colorbox{growth!25}{\parbox{0.8\linewidth}{{\fontsize{32}{40}\selectfont\bfseries\color{growth} positive MoM} growth}}}
    \pbullet{IBM grew \colorbox{growth!25}{\parbox{0.8\linewidth}{{\fontsize{32}{40}\selectfont\bfseries\color{growth} +46\%} in active contributors}}}
    \pbullet{Google added \colorbox{growth!25}{\parbox{0.8\linewidth}{{\fontsize{32}{40}\selectfont\bfseries\color{growth} +128} new contributors}}}
  \end{itemize}
}

% ══ KEY INSIGHT ════════════════════════════════════════════════════
\posterbox[
  enhanced, colback=carddark, boxrule=0pt, arc=0pt,
  left=20pt, right=20pt, top=8pt, bottom=8pt,
  halign=center, valign=center,
  borderline={3pt}{0pt}{accent!40},
  drop shadow={opacity=0.25}
]{name=insight, column=1, span=3, between=row17 and row19}{
  {\fontsize{34}{44}\selectfont\color{textmuted} Python dominates at 20.3\% \quad $\bullet$ \quad Apache-2.0 leads license usage \quad $\bullet$ \quad All top 10 orgs showing MoM growth}
}

% ══ FOOTER ══════════════════════════════════════════════════════════
\posterbox[
  enhanced, colback=secondary!60!primary, boxrule=0pt, arc=0pt,
  left=20pt, right=20pt, top=4pt, bottom=4pt,
  halign=center, valign=middle
]{name=footer, column=1, span=3, between=row19 and bottom}{
  {\fontsize{24}{32}\selectfont\color{textmuted} Open Source Contributor Index (OSCI) \quad $\bullet$ \quad Data as of March 2026 \quad $\bullet$ \quad Index is open source (GPL v3.0)}
}

\end{tcbposter}
\end{document}

